package benchmark;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.*;
import bms.player.beatoraja.skin.property.*;
@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations=2,time=500,timeUnit=TimeUnit.MILLISECONDS)
@Measurement(iterations=3,time=500,timeUnit=TimeUnit.MILLISECONDS)
@Fork(value=2,jvmArgsAppend={"-Xms512m","-Xmx512m"})
public class MissingPropertyBenchmark {
 @Param({"known", "missing"}) public String kind;
 private int numberId, imageId, booleanId;
 @Setup public void setup() {
  numberId=kind.equals("known")?74:65535;
  imageId=kind.equals("known")?303:65535;
  booleanId=kind.equals("known")?bms.player.beatoraja.skin.SkinProperty.OPTION_TABLE_SONG:65535;
  if((IntegerPropertyFactory.getIntegerProperty(numberId)!=null)!=kind.equals("known")) throw new AssertionError("number ID");
  if((IntegerPropertyFactory.getImageIndexProperty(imageId)!=null)!=kind.equals("known")) throw new AssertionError("image ID");
  if((BooleanPropertyFactory.getBooleanProperty(booleanId)!=null)!=kind.equals("known")) throw new AssertionError("boolean ID");
  BooleanPropertyFactory.getBooleanProperty(-booleanId);
 }
 @Benchmark public IntegerProperty number() { return IntegerPropertyFactory.getIntegerProperty(numberId); }
 @Benchmark public IntegerProperty image() { return IntegerPropertyFactory.getImageIndexProperty(imageId); }
 @Benchmark public BooleanProperty option() { return BooleanPropertyFactory.getBooleanProperty(booleanId); }
 @Benchmark public BooleanProperty negativeOption() { return BooleanPropertyFactory.getBooleanProperty(-booleanId); }
}
